"""# DAY 7

SET

Set is a collection of items. Let me take you back to your elementary or high school Mathematics lesson. The Mathematics definition of a set can be applied also in Python. Set is a collection of unordered and un-indexed distinct elements. In Python set is used to store unique items, and it is possible to find the union, intersection, difference, symmetric difference, subset, super set and disjoint set among sets.
"""

#create a set
empty_set = {}
print(empty_set)
#use {} create a dictionary
fruits = {'banana', 'orange', 'mango', 'lemon'}
len(fruits)

#checking item in a set
print("Does banana contain in fruits ",'banana' in fruits)
#update
fruits = {'banana', 'orange', 'mango', 'lemon'}
vegetables = {'tomato', 'potato', 'cabbage','onion', 'carrot'}
fruits.update(vegetables)
print(fruits)
# join 2 sets
st1 = {'item1', 'item2', 'item3', 'item4'}
st2 = {'item5', 'item6', 'item7', 'item8'}
st3 = st1.union(st2)

#check the true
st = {"it1","it2","it3"}
print("Does it1 include in st", "it1" in st)

st = {'item1', 'item2', 'item3', 'item4'}
st.add('item5')
print(st) #ko có thứ tự nên sẽ cho ra nhiều lần chạy khác nhau
fruits = {'banana', 'orange', 'mango', 'lemon'}
vegetables = ('tomato', 'potato', 'cabbage','onion', 'carrot')
fruits.update(vegetables)
print(fruits)

#conver list to set
fruits = ['banana', 'orange', 'mango', 'lemon','orange', 'banana']
fruits = set(fruits)
print(fruits)
#ngoài ra còn các syntax tìm union, intersection, symmetric, issubset, issuper set


python = {'p', 'y', 't', 'h', 'o','n'}
dragon = {'d', 'r', 'a', 'g', 'o','n'}
python.symmetric_difference(dragon)  # {'r', 't', 'p', 'y', 'g', 'a', 'd', 'h'}
# python ^ dragon

