""" * Check if the person dictionary has skills key, if so print out the middle skill in the skills list.
 * Check if the person dictionary has skills key, if so check if the person has 'Python' skill and print out the result.
 * If a person skills has only JavaScript and React, print('He is a front end developer'), if the person skills has Node, Python, MongoDB, print('He is a backend developer'), if the person skills has React, Node and MongoDB, Print('He is a fullstack developer'), else print('unknown title') - for more accurate results more conditions can be nested!
 * If the person is married and if he lives in Finland, print the information in the following format:
"""

does_it_has_skill = input("Enter skills:")
if does_it_has_skill in person['skills']:
  length= len(person['skills'])//2 -1 #neu ko tru 1 thi se in ra Mongo vi Python hieu thu tu khac nhau
  print("Yes, this person has skill and middle skill is" ,person['skills'][length])
else:
  print("This person does not have skill")

name = str(input("Enter your name:"))
country = str(input("Enter country:"))
if name == person['first_name'] and country == person['country']:
  print("His name is", name, "and live in", country)
else:
  print("Not him")

skills = person['skills']

if 'JavaScript' in skills and 'React' in skills:
    print("He is a front end developer")

elif 'Node' in skills and 'Python' in skills and 'MongoDB' in skills:
    print("He is a backend developer")

elif 'React' in skills and 'Node' in skills and 'MongoDB' in skills:
    print("He is a fullstack developer")

else:
    print("Unknown title")
