import json

with open('countries_data.py', 'r') as f:
    countries = json.load(f)
all_languages = set()
for country in countries:
    for language in country['languages']:
      all_languages.add(language)
print(len(all_languages))

most_popular_language = {} #tạo 1 dict
for country in countries: #vòng lặp country trong countries
  for language in country['languages']: #xét đến biến languague trong count(lan)
    if language in most_popular_language: #nếu lan đó có trong most popular thì cộng thêm 1 nếu ko thì bằng 1 , ví dụ vietnam in {} là false thì vietnam sẽ là 1 ...
      most_popular_language[language] += 1
    else:
      most_popular_language[language] = 1

sorted_langguages = sorted(most_popular_language.items(), key=lambda x: x[1],reverse=True)
print(sorted_langguages[:10])

most_population ={} #tạo 1 dict syntax gắn value vô dict dct['key5'] = 'value5'
for country in countries: #ví dụ viet nam in countries thì most_population[Country['Vietnam]] = 90 triệu người chẳng hạn
  most_population[country['name']] = country['population']

sorted_population = sorted(most_population.items(), key=lambda x: x[1],reverse=True)
print(sorted_population[:10])

